"use client";
import { useMemo, useState } from "react";
import {
  Bar,
  BarChart,
  Rectangle,
  ResponsiveContainer,
  Tooltip,
  XAxis,
  YAxis,
  type RectangleProps,
} from "recharts";
import { useHydratedReducedMotion } from "../../hooks/use-hydrated-reduced-motion";
import { cx } from "../../utils/cx";
import { AXIS, ChartCard, formatNumber, useChartHover } from "./chart-card";
import { ChartBarTrack } from "./chart-bar-track";
import { EARNINGS_DEMO_RANGES } from "./chart-demo-data";
import {
  type ChartCommonProps,
  type ChartRange,
  PeriodTabs,
  numeric,
  safeRatio,
  sum,
  useChartRange,
} from "./pro-chart";

export interface EarningsPoint {
  label: string;
  fullLabel?: string;
  value: number;
}
export interface EarningsChartRange extends ChartRange {
  data: EarningsPoint[];
}
export interface EarningsChartCardProps extends ChartCommonProps {
  data?: EarningsPoint[];
  ranges?: EarningsChartRange[];
  color?: string;
  max?: number;
}
export const EARNINGS_DATA: EarningsPoint[] = EARNINGS_DEMO_RANGES[0]!.data;
const RANGES: EarningsChartRange[] = EARNINGS_DEMO_RANGES;
type BarGeometry = RectangleProps & { index?: number };

export function EarningsChartCard({
  data,
  ranges: supplied,
  title = "Earned so far",
  color = "var(--color-chart-2)",
  max,
  ...props
}: EarningsChartCardProps = {}) {
  const ranges = supplied ?? (data ? undefined : RANGES);
  const period = useChartRange(ranges, props.defaultRange, props.onRangeChange);
  const points = period.current?.data ?? data ?? EARNINGS_DATA;
  const hover = useChartHover(),
    active = hover.activeIndex;
  const reduced = useHydratedReducedMotion();
  const [plotDelay, setPlotDelay] = useState(0);
  const requestedCeiling =
    max ?? (data || supplied ? Math.max(1, ...points.map((p) => numeric(p.value))) * 1.04 : 12000);
  const ceiling = Number.isFinite(requestedCeiling) && requestedCeiling > 0 ? requestedCeiling : 1;
  const plotPoints = useMemo(
    () =>
      points.map((point) => ({
        ...point,
        plotValue: safeRatio(point.value, requestedCeiling) * ceiling,
      })),
    [points, requestedCeiling, ceiling],
  );
  const format = props.format ?? ((n: number) => `$${formatNumber(n)}`);
  const change = period.current?.delta ?? props.delta;
  return (
    <ChartCard
      label={active == null ? title : (points[active]?.fullLabel ?? points[active]?.label ?? title)}
      value={
        active == null
          ? (period.current?.headline ?? props.headline ?? sum(points.map((p) => p.value)))
          : (points[active]?.value ?? 0)
      }
      formatValue={format}
      roundValue={props.format == null}
      delta={
        active == null && change != null
          ? {
              label: `${change > 0 ? "+" : ""}${+(change * 100).toFixed(1)}%`,
              color: change >= 0 ? "lime" : "rose",
            }
          : undefined
      }
      pulseKey={active}
      className={cx("w-full flex-none xl:w-[673px] xl:shrink-0", props.className)}
      height={329}
      action={
        ranges && (
          <PeriodTabs
            ranges={ranges}
            selected={period.id}
            onChange={(id) => {
              setPlotDelay(320);
              period.select(id);
            }}
          />
        )
      }
    >
      <ResponsiveContainer width="100%" height="100%">
        <BarChart
          data={plotPoints}
          margin={{ top: 4, right: 0, left: 0, bottom: 0 }}
          barCategoryGap="18%"
          {...hover.handlers}
        >
          <YAxis
            {...AXIS}
            width={44}
            domain={[0, ceiling]}
            ticks={[0, ceiling * 0.25, ceiling * (5 / 12), ceiling * (10 / 12)]}
            tickFormatter={(n) => (n === 0 ? "$0" : `$${Math.round(n / 1000)}K`)}
          />
          <XAxis {...AXIS} dataKey="label" tick={{ ...AXIS.tick, fontSize: 13 }} tickMargin={12} />
          <Tooltip content={() => null} cursor={false} />
          <Bar
            dataKey="plotValue"
            maxBarSize={data || supplied ? 32 : undefined}
            fill={color}
            radius={10}
            isAnimationActive={!reduced}
            animationDuration={450}
            animationBegin={plotDelay}
            animationEasing="ease"
            background={(value: unknown) => {
              const p = value as BarGeometry;
              return <ChartBarTrack {...p} active={active === p.index} />;
            }}
            shape={(value: unknown) => {
              const p = value as BarGeometry,
                index = p.index ?? 0,
                point = points[index];
              return (
                <g
                  role="button"
                  tabIndex={-1}
                  aria-label={`${point?.label}: ${format(point?.value ?? 0)}`}
                  onMouseDown={(event) => event.preventDefault()}
                  onClick={() => hover.setActiveIndex(index)}
                  onFocus={() => hover.setActiveIndex(index)}
                  onBlur={hover.clear}
                >
                  <Rectangle
                    {...p}
                    radius={10}
                    fill={
                      active === index && color === "var(--color-chart-2)"
                        ? "var(--color-chart-2-active)"
                        : color
                    }
                  />
                </g>
              );
            }}
          />
        </BarChart>
      </ResponsiveContainer>
    </ChartCard>
  );
}
